def compute(vars):
    old_value = vars["v1"]
    new_value = vars["v2"]
    difference = new_value - old_value

    if old_value == 0:
        return {
            "value": None,
            "trace": {
                "old_value": old_value,
                "new_value": new_value,
                "difference": difference,
                "output_meta": {
                    "currency": None,
                    "scale": None,
                    "unit": "percentage"
                }
            }
        }

    change_ratio = difference / old_value
    percent_change = change_ratio * 100

    return {
        "value": percent_change,
        "trace": {
            "old_value": old_value,
            "new_value": new_value,
            "difference": difference,
            "change_ratio": change_ratio,
            "output_meta": {
                "currency": None,
                "scale": None,
                "unit": "percentage"
            }
        }
    }
